#!/usr/bin/env python3
from pathlib import Path

path = Path("linktools-ai/src/linktools/ai/runtime/_runtime_service.py")
value = path.read_text(encoding="utf-8")
value = value.replace("from typing import Protocol, TypeGuard", "from typing import Protocol")
value = value.replace(
    "from ..agent import (\n    AgentBindingSnapshot,",
    "from ..agent import (\n    AgentBinding,\n    AgentBindingSnapshot,",
)
value = value.replace(
    '_AGENT_TASK_LEGACY_V1_FIELDS = frozenset({"type", "version", "agent_id", "user_prompt"})\n_AGENT_TASK_CURRENT_V1_FIELDS = frozenset(\n    {\n        "type",\n        "version",\n        "agent_id",\n        "binding_digest",\n        "binding",\n        "user_prompt",\n        "planning",\n        "thinking",\n    }\n)\n',
    '_AGENT_TASK_FIELDS = frozenset({"type", "version", "binding", "user_prompt", "planning", "thinking"})\n',
)
value = value.replace(
    '''    async def resume(\n        self,\n        binding_digest: str,\n        session_id: str,\n        request: ResumeSessionRequest,\n    ) -> ExecutionHandle: ...''',
    '''    async def resume(\n        self,\n        agent_digest: str,\n        binding_digest: str,\n        session_id: str,\n        request: ResumeSessionRequest,\n    ) -> ExecutionHandle: ...''',
)

start = value.index("    def agent(\n")
end = value.index("    async def cancel(\n", start)
block = '''    def agent(\n        self,\n        agent: "str | AgentSpec" = "default",\n        *,\n        capabilities: "Sequence[RuntimeCapability]" = (),\n    ) -> AgentHandle:\n        self._ensure_open()\n        if any(not isinstance(capability, RuntimeCapability) for capability in capabilities):\n            raise TypeError("capabilities must contain RuntimeCapability values")\n        if isinstance(agent, str):\n            validate_agent_id(agent)\n            base = self._catalog.root_definition(agent)\n            definition = (\n                base\n                if not capabilities\n                else self._compiler.compile(base.spec, capabilities=capabilities)\n            )\n        elif isinstance(agent, AgentSpec):\n            definition = self._compiler.compile(agent, capabilities=capabilities)\n        else:\n            raise TypeError("agent must be an Agent id or AgentSpec")\n        definition = self._catalog.register_definition(definition)\n        return AgentHandle(self, definition.spec.id, definition.digest)\n\n    def _definition(self, agent_digest: str) -> AgentDefinition:\n        self._ensure_open()\n        return self._catalog.definition(agent_digest)\n\n    def _binding(self, binding_digest: str) -> AgentBinding:\n        self._ensure_open()\n        return self._catalog.binding(binding_digest)\n\n    def _bind_definition(\n        self,\n        definition: AgentDefinition,\n        *,\n        output: "type[BaseModel] | None" = None,\n    ) -> AgentBinding:\n        return self._catalog.register_binding(\n            self._compiler.bind(definition, output=output)\n        )\n\n    def _restore_binding(self, snapshot: AgentBindingSnapshot) -> AgentBinding:\n        self._ensure_open()\n        try:\n            current = self._catalog.binding(snapshot.binding_digest)\n        except AIError as error:\n            if error.code is not ErrorCode.AGENT_DEFINITION_UNAVAILABLE:\n                raise\n        else:\n            if current.snapshot != snapshot:\n                raise AIError(ErrorCode.STORAGE_INTEGRITY_ERROR)\n            return current\n        try:\n            restored = self._compiler.restore(snapshot)\n        except AIError as error:\n            if error.code is ErrorCode.STORAGE_INTEGRITY_ERROR:\n                raise\n            raise AIError(ErrorCode.AGENT_DEFINITION_UNAVAILABLE) from error\n        return self._catalog.register_binding(restored)\n\n    async def _compile_agent(self, agent_id: str) -> AgentDefinition:\n        self._ensure_open()\n        return self._catalog.root_definition(agent_id)\n\n    async def _start_for_agent(\n        self,\n        agent_digest: str,\n        user_prompt: str,\n        *,\n        output: "type[BaseModel] | None",\n        principal: "Principal | None",\n        session_id: "str | None",\n        idempotency_key: "str | None",\n        memory_scope: "str | None",\n        planning: bool,\n        thinking: bool,\n        local_stream: bool = False,\n    ) -> ExecutionHandle:\n        self._ensure_open()\n        if not isinstance(planning, bool) or not isinstance(thinking, bool):\n            raise AIError(ErrorCode.REQUEST_FIELD_INVALID)\n        principal = self._resolve_principal(principal)\n        validate_user_prompt(user_prompt)\n        definition = self._catalog.definition(agent_digest)\n        binding = self._bind_definition(definition, output=output)\n        request = ExecutionRequest(\n            user_prompt=user_prompt,\n            principal=principal,\n            idempotency_key=idempotency_key or secrets.token_urlsafe(32),\n            memory_scope=_validate_memory_scope(memory_scope),\n            planning=planning,\n            thinking=thinking,\n        )\n        if session_id is None:\n            if local_stream and self._local_coordinator is not None:\n                handle = await self._local_coordinator.run(binding.digest, request)\n            else:\n                handle = await self.execution.run(binding.digest, request)\n        else:\n            if not session_id.strip():\n                raise AIError(ErrorCode.REQUEST_FIELD_INVALID)\n            await self._ensure_session(definition, session_id, principal)\n            resume_request = ResumeSessionRequest(\n                principal=principal,\n                user_prompt=user_prompt,\n                idempotency_key=request.idempotency_key or "",\n                memory_scope=request.memory_scope,\n                planning=planning,\n                thinking=thinking,\n            )\n            if local_stream and self._local_coordinator is not None:\n                handle = await self._local_coordinator.resume(\n                    definition.digest, binding.digest, session_id, resume_request\n                )\n            else:\n                handle = await self.session.resume(\n                    definition.digest, binding.digest, session_id, resume_request\n                )\n        _logger.info(\n            "runtime execution admitted: execution=%s agent=%s session=%s planning=%s thinking=%s",\n            handle.execution_id, definition.spec.id, session_id, planning, thinking,\n        )\n        return handle\n\n    async def _run_for_agent(\n        self,\n        agent_digest: str,\n        user_prompt: str,\n        *,\n        output: "type[BaseModel] | None",\n        principal: "Principal | None",\n        session_id: "str | None",\n        idempotency_key: "str | None",\n        memory_scope: "str | None",\n        planning: bool,\n        thinking: bool,\n        timeout_seconds: "float | None",\n    ) -> ExecutionResult:\n        principal = self._resolve_principal(principal)\n        handle = await self._start_for_agent(\n            agent_digest, user_prompt, output=output, principal=principal,\n            session_id=session_id, idempotency_key=idempotency_key,\n            memory_scope=memory_scope, planning=planning, thinking=thinking,\n        )\n        return await self.execution.wait(\n            handle.execution_id, principal=principal, timeout_seconds=timeout_seconds\n        )\n\n'''
value = value[:start] + block + value[end:]

start = value.index("    def stream(\n")
end = value.index("    async def run_graph(\n", start)
block = '''    def _stream_for_agent(\n        self,\n        agent_digest: str,\n        user_prompt: str,\n        *,\n        output: "type[BaseModel] | None",\n        principal: "Principal | None",\n        session_id: "str | None",\n        idempotency_key: "str | None",\n        memory_scope: "str | None",\n        planning: bool,\n        thinking: bool,\n    ) -> AsyncIterator[ExecutionStreamEvent]:\n        principal = self._resolve_principal(principal)\n        return self._stream_agent(\n            agent_digest, user_prompt, output=output, principal=principal,\n            session_id=session_id, idempotency_key=idempotency_key,\n            memory_scope=memory_scope, planning=planning, thinking=thinking,\n        )\n\n    async def _stream_agent(\n        self,\n        agent_digest: str,\n        user_prompt: str,\n        *,\n        output: "type[BaseModel] | None",\n        principal: Principal,\n        session_id: "str | None",\n        idempotency_key: "str | None",\n        memory_scope: "str | None",\n        planning: bool,\n        thinking: bool,\n    ) -> AsyncIterator[ExecutionStreamEvent]:\n        handle = await self._start_for_agent(\n            agent_digest, user_prompt, output=output, principal=principal,\n            session_id=session_id, idempotency_key=idempotency_key,\n            memory_scope=memory_scope, planning=planning, thinking=thinking,\n            local_stream=self._local_coordinator is not None,\n        )\n        stream = (\n            self.event.stream(handle.execution_id, principal=principal)\n            if self._local_coordinator is None\n            else self._local_coordinator.stream(handle.execution_id, principal=principal)\n        )\n        async for event in stream:\n            yield event\n\n    async def _create_session_for_agent(\n        self,\n        agent_digest: str,\n        session_id: str,\n        *,\n        principal: "Principal | None",\n        cwd: "str | None",\n        metadata: "Mapping[str, JsonValue] | None",\n    ) -> SessionView:\n        principal = self._resolve_principal(principal)\n        definition = self._catalog.definition(agent_digest)\n        values = dict(metadata or {})\n        if any(key.startswith("linktools.ai.") for key in values):\n            raise AIError(ErrorCode.REQUEST_FIELD_INVALID)\n        values["linktools.ai.agent_id"] = definition.spec.id\n        return await self.session.create(\n            definition.digest,\n            CreateSessionRequest(\n                principal, session_id, secrets.token_urlsafe(32), cwd, values\n            ),\n        )\n\n    async def _run_evaluation_for_agent(\n        self,\n        agent_digest: str,\n        request: RunEvaluationRequest,\n        *,\n        output: "type[BaseModel] | None",\n    ) -> EvaluationHandle:\n        definition = self._catalog.definition(agent_digest)\n        binding = self._bind_definition(definition, output=output)\n        return await self.evaluation.run(\n            binding.digest, binding.output_schema_fingerprint, request\n        )\n\n    async def _replay_evaluation_for_agent(\n        self,\n        agent_digest: str,\n        snapshot_id: str,\n        request: ReplayEvaluationRequest,\n        *,\n        output: "type[BaseModel] | None",\n    ) -> ExecutionHandle:\n        definition = self._catalog.definition(agent_digest)\n        binding = self._bind_definition(definition, output=output)\n        return await self.evaluation.replay(binding.digest, snapshot_id, request)\n\n    def _task_for_agent(\n        self,\n        agent_digest: str,\n        node_id: str,\n        user_prompt: str,\n        *,\n        dependencies: tuple[str, ...],\n        budget_cost: int,\n        output: "type[BaseModel] | None",\n        planning: bool,\n        thinking: bool,\n    ) -> TaskNode:\n        self._ensure_open()\n        validate_user_prompt(user_prompt)\n        if not isinstance(planning, bool) or not isinstance(thinking, bool):\n            raise AIError(ErrorCode.REQUEST_FIELD_INVALID)\n        definition = self._catalog.definition(agent_digest)\n        binding = self._bind_definition(definition, output=output)\n        return TaskNode(\n            node_id,\n            dependencies,\n            input={\n                "type": "linktools.ai.agent",\n                "version": 1,\n                "binding": binding.snapshot.to_payload(),\n                "user_prompt": user_prompt,\n                "planning": planning,\n                "thinking": thinking,\n            },\n            budget_cost=budget_cost,\n        )\n\n'''
value = value[:start] + block + value[end:]

# Canonical TaskGraph V1 admission.
start = value.index("    async def _admit_graph(\n")
end = value.index("    async def _ensure_session(\n", start)
old_graph = value[start:end]
header_end = old_graph.index("        admitted_nodes: list[TaskNode] = []")
prefix = old_graph[:header_end]
new_tail = '''        admitted_nodes: list[TaskNode] = []\n        agent_ids: set[str] = set()\n        for node in graph.nodes:\n            payload = node.input\n            if (\n                payload.get("type") != "linktools.ai.agent"\n                or payload.get("version") != 1\n                or frozenset(payload) != _AGENT_TASK_FIELDS\n            ):\n                raise AIError(ErrorCode.REQUEST_FIELD_INVALID)\n            user_prompt = payload.get("user_prompt")\n            planning = payload.get("planning")\n            thinking = payload.get("thinking")\n            if (\n                not isinstance(user_prompt, str)\n                or not isinstance(planning, bool)\n                or not isinstance(thinking, bool)\n            ):\n                raise AIError(ErrorCode.REQUEST_FIELD_INVALID)\n            try:\n                snapshot = AgentBindingSnapshot.from_payload(payload.get("binding"))\n                binding = self._restore_binding(snapshot)\n            except AIError as error:\n                raise AIError(ErrorCode.REQUEST_FIELD_INVALID) from error\n            validate_user_prompt(user_prompt)\n            agent_ids.add(binding.definition.spec.id)\n            admitted_nodes.append(\n                TaskNode(\n                    node.node_id,\n                    node.dependencies,\n                    input={\n                        "type": "linktools.ai.agent",\n                        "version": 1,\n                        "binding": binding.snapshot.to_payload(),\n                        "user_prompt": user_prompt,\n                        "planning": planning,\n                        "thinking": thinking,\n                    },\n                    budget_cost=node.budget_cost,\n                )\n            )\n        admitted = TaskGraph(graph.graph_id, tuple(admitted_nodes))\n        _logger.info(\n            "agent task graph admitted: graph=%s tenant=%s agents=%s nodes=%s",\n            graph.graph_id, principal.tenant_id, tuple(sorted(agent_ids)), len(admitted.nodes),\n        )\n        return TaskGraphRequest(admitted, principal, idempotency_key, selected_limits)\n\n'''
value = value[:start] + prefix + new_tail + value[end:]

# Session validation uses Agent identity only.
start = value.index("    async def _ensure_session(\n")
end = value.index("    def _ensure_open(\n", start)
session_block = '''    async def _ensure_session(\n        self,\n        definition: AgentDefinition,\n        session_id: str,\n        principal: Principal,\n    ) -> None:\n        try:\n            session = await self.session.get(session_id, principal=principal)\n        except AIError as error:\n            if error.code not in {ErrorCode.SESSION_NOT_FOUND, ErrorCode.AUTHORIZATION_DENIED}:\n                raise\n            try:\n                await self.session.create(\n                    definition.digest,\n                    CreateSessionRequest(\n                        principal, session_id, secrets.token_urlsafe(32), None,\n                        {"linktools.ai.agent_id": definition.spec.id},\n                    ),\n                )\n                return\n            except AIError as create_error:\n                if create_error.code is not ErrorCode.STORAGE_CONFLICT:\n                    raise\n            session = await self.session.get(session_id, principal=principal)\n        if session.status is not SessionStatus.OPEN:\n            raise AIError(ErrorCode.SESSION_CONFLICT)\n        if session.agent_digest != definition.digest:\n            raise AIError(ErrorCode.SESSION_BINDING_MISMATCH)\n\n'''
value = value[:start] + session_block + value[end:]
path.write_text(value, encoding="utf-8")
